entries[101630] = { ["name"] = "Nudelwagenbausatz", ["text"] = "Benötigt Stufe 90\nBenutzen: Baut einen Nudelwagen auf, um Nudelsuppe zu verkaufen!\n\nJede Suppe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 250 erhöht.\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen zu bauen.\"\nVerkaufspreis:" }
entries[101631] = { ["name"] = "Rezept: Nudelwagenbausatz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Kochkunst (600)\nBenutzen: Lehrt Euch, wie man einen Nudelwagenbausatz erschafft.\nVerkaufspreis:\nNudelwagenbausatz\nBenötigt Stufe 90\nBenutzen: Baut einen Nudelwagen auf, um Nudelsuppe zu verkaufen!\n\nJede Suppe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 250 erhöht.\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen zu bauen.\"\nVerkaufspreis:\nBenötigt Gegrilltes Tigersteak (5), Gebratene Karotten (5), Verwirbelte Nebelsuppe (5), Garnelenklößchen (5), Wildgeflügelbraten (5), Ginsengtee (5)" }
