entries[101661] = { ["name"] = "Nudelwagenbausatz Deluxe", ["text"] = "Benötigt Stufe 90\nBenutzen: Baut einen Nudelwagen Deluxe auf, um Nudelsuppe Deluxe zu verkaufen!\n\nJede Nudelsuppe Deluxe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht.\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen Deluxe zu bauen.\"\nVerkaufspreis:" }
entries[101662] = { ["name"] = "Nudelwagenbausatz \"Pandarenschatz\"", ["text"] = "Benötigt Stufe 90\nBenutzen: Baut einen Nudelwagen \"Pandarenschatz\" auf, um Nudelsuppe \"Pandarenschatz\" zu verkaufen!\n\nJede Suppe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 300 erhöht.\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen \"Pandarenschatz\" zu bauen.\"\nVerkaufspreis:" }
entries[101663] = { ["name"] = "Rezept: Nudelwagenbausatz \"Pandarenschatz\"", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Kochkunst (600)\nBenutzen: Lehrt Euch, wie man einen Nudelwagenbausatz \"Pandarenschatz\" erschafft.\nVerkaufspreis:\nNudelwagenbausatz \"Pandarenschatz\"\nBenötigt Stufe 90\nBenutzen: Baut einen Nudelwagen \"Pandarenschatz\" auf, um Nudelsuppe \"Pandarenschatz\" zu verkaufen!\n\nJede Suppe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 300 erhöht.\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen \"Pandarenschatz\" zu bauen.\"\nVerkaufspreis:\nBenötigt Rippchen mit schwarzem Pfeffer und Garnelen (5), Chun-Tian-Frühlingsrollen (5), Fischeintopf nach Moguart (5), Gedämpfte Krabbe à la Surprise (5), Küstennebelreisnudeln (5), Wahnsinniges Brauerfrühstück (5)" }
entries[101664] = { ["name"] = "Rezept: Nudelwagenbausatz Deluxe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Kochkunst (600)\nBenutzen: Lehrt Euch, wie man einen Nudelwagenbausatz Deluxe erschafft.\nVerkaufspreis:\nNudelwagenbausatz Deluxe\nBenötigt Stufe 90\nBenutzen: Baut einen Nudelwagen Deluxe auf, um Nudelsuppe Deluxe zu verkaufen!\n\nJede Nudelsuppe Deluxe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht.\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen Deluxe zu bauen.\"\nVerkaufspreis:\nBenötigt Blütenfischfilet (5), Zwillingsfischplatte (5), Geschmorte Schildkröte (5), Feuergeisterlachs (5), Pfannengericht nach Vier-Winde-Art (5), Jadehexenbräu (5)" }
