entries[102312] = { ["name"] = "5.4 Raid - Normal - Siege of Orgrimmar - Boss X Loot X - Agi DPS Trinket (5)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.959 Beweglichkeit\nBenötigt Stufe 90\nAnlegen: Wenn Eure Angriffe treffen, besteht eine Chance, dass Ihr 20 Sek. lang 11761 Meisterschaft erhaltet. (15% Chance, 115 Sek. Abklingzeit) (Procchance: 15%, 1.917Min. Abklingzeit)\nVerkaufspreis:" }
entries[102313] = { ["name"] = "5.4 Raid - Normal - Siege of Orgrimmar - Boss X Loot X - Int Hit Trinket (5)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.959 Intelligenz\nBenötigt Stufe 90\nAnlegen: Wenn Eure Zauber Schaden verursachen, besteht eine Chance, 20 Sek. lang zusätzlich 11761 kritischen Trefferwert zu erhalten. (15% Chance, 115 Sek. Abklingzeit) (Procchance: 15%, 1.917Min. Abklingzeit)\nVerkaufspreis:" }
entries[102314] = { ["name"] = "5.4 Raid - Normal - Siege of Orgrimmar - Boss X Loot X - Int Spirit Trinket (5)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.959 Intelligenz\nBenötigt Stufe 90\nBenutzen: Erhöht Eure Willenskraft 15 Sek. lang um 9795 . (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[102315] = { ["name"] = "5.4 Raid - Normal - Siege of Orgrimmar - Boss X Loot X - Str DPS Trinket (5)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.959 Stärke\nBenötigt Stufe 90\nAnlegen: Jedes Mal, wenn Eure Nahkampfangriffe treffen, besteht eine Chance, dass Ihr 20 Sek. lang 11761 Tempo erhaltet. (15% Chance, 115 Sek. Abklingzeit) (Procchance: 15%, 1.917Min. Abklingzeit)\nVerkaufspreis:" }
