entries[102463] = { ["name"] = "Eid des Feuerwächters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verwandelt Euch in einen Feuerwächter von Ordos. Wenn Ihr in diesem Zustand andere Spielercharaktere tötet, besteht eine Chance, blutige Münzen zu erhalten. (1s Abklingzeit) (10 Min Abklingzeit)\n\"Feuerwächter von Ordos tragen die Asche ihrer Opfer in einem besonderen Beutel mit sich herum, in dem sie weiterglüht.\"" }
entries[102464] = { ["name"] = "Schwarze Asche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bedeckt den Gegner mit Asche und verringert so die auf ihn gewirkte Heilung 10 Sek. lang um 90%. Nur auf der Zeitlosen Insel verwendbar.\n\"Die zu Asche zerfallenen Überreste eines Opfers für Ordos.\"" }
entries[102467] = { ["name"] = "Rauchbrenner der ewigen Pein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Opfert 90% Eurer maximalen Gesundheit, um ein Abgesandter von Ordos zu werden. Während Ihr verwandelt seid, seid Ihr allen Spielercharakteren feindlich gesinnt und das Töten anderer Spielercharaktere gewährt blutige Münzen. Kann nur auf der Zeitlosen Insel verwendet werden und markiert Euch für den PvP-Kampf. (1s Abklingzeit) (1 Stunde Abklingzeit)\n\"Ein rituelles Opfer ist erforderlich, um ein Anhänger von Ordos zu werden.\"" }
